={{ (() => {
  const d = $('Llamar Redactor').first().json.data;
  const partes = [
    `**Asunto:** ${d.asunto}`,
    d.cover_letter,
    '---',
    'Revisá la carta antes de enviarla: es una propuesta basada en tu CV.'
  ];
  if (d.requisitos_sin_respaldo && d.requisitos_sin_respaldo.length) {
    partes.push('**Requisitos de la vacante que no afirmé en la carta**\n' + d.requisitos_sin_respaldo.map(x => '- ' + x).join('\n'));
  }
  return partes.join('\n\n');
})() }}

={{ (() => {
  const d = $json.data;
  const r = $('Recepcionista').first().json.output;
  const lista = (xs) => (xs || []).map(x => '- ' + x).join('\n');
  const partes = [
    `**${d.rol} · ${d.empresa}**`,
    `**Match:** ${d.match}. ${d.match_motivo}`,
    `**Elegibilidad:** ${d.elegibilidad}. ${d.elegibilidad_motivo}`
  ];
  if (r.mensaje_al_usuario) {
    partes.unshift(r.mensaje_al_usuario);
  }
  if (d.encaje_criterios && d.encaje_criterios.resultado !== 'no_evaluado') {
    partes.push(`**Encaje con tus criterios:** ${d.encaje_criterios.resultado}\n${lista(d.encaje_criterios.motivos)}`);
  }
  if (d.mensaje_central) {
    partes.push(`**Tu mensaje central para esta vacante**\n${d.mensaje_central}`);
  }
  partes.push(`**Fortalezas**\n${lista(d.fortalezas)}`);
  partes.push(`**Gaps**\n${lista(d.gaps)}`);
  if (d.experiencias_a_destacar && d.experiencias_a_destacar.length) {
    partes.push('**Qué destacar de tu experiencia**\n' + d.experiencias_a_destacar.map(e => `- ${e.experiencia} (cubre: ${e.cubre}). En tu CV: "${e.evidencia_en_cv}"`).join('\n'));
  }
  partes.push(`**Qué priorizar en tu CV**\n${lista(d.guia_cv && d.guia_cv.priorizar)}`);
  if (!r.criterios_url) {
    partes.push('Si compartís tu documento de criterios de búsqueda, también evalúo si la vacante encaja con lo que buscás.');
  }
  return partes.join('\n\n');
})() }}

