{{ JSON.stringify((function limpiar(v) {
  if (typeof v === 'string') {
    try { const o = JSON.parse(v); if (o && typeof o === 'object') return JSON.stringify(limpiar(o)); } catch (e) {}
    return v.length > 500 ? '[texto largo omitido: probablemente una vacante]' : v;
  }
  if (Array.isArray(v)) return v.map(limpiar);
  if (v && typeof v === 'object') {
    const r = {};
    for (const k of Object.keys(v)) {
      if (['vacante_texto', 'cv_url', 'criterios_url'].includes(k)) continue;
      r[k] = limpiar(v[k]);
    }
    return r;
  }
  return v;
})($json.messages || [])) }}
[/HISTORIAL]

